<script setup>
import { ref, computed, onMounted, onUnmounted, watch } from 'vue';
import { Sparkles, RefreshCw, Check, Plus, Upload, Download, ShieldCheck, ExternalLink, Trash2 } from 'lucide-vue-next';
const props=defineProps({mode:String,section:String,companyId:String,company:Object,user:Object,posts:Array,api:Function,headers:Function});
const emit=defineEmits(['task','compose','updated']);
const data=ref(null),settings=ref(null),control=ref(null),busy=ref(false),error=ref(''),notice=ref('');
const selectedKind=ref('topics'),request=ref(''),artifactKind=ref('all'),channel=ref({name:'',url:''}),channelFilter=ref('all'),rankMode=ref('relative'),days=ref(30),report=ref(null);
const connections=ref({vk:{},max:{}}),providerView=ref('codex'),providerForms=ref({});
const from=ref(new Date(Date.now()-30*86400000).toISOString().slice(0,10)),to=ref(new Date().toISOString().slice(0,10));
const metric=ref({post_id:'',date:new Date().toISOString().slice(0,10),reactions:'',comments:''});
const approvers=ref(''),admins=ref(''),newSkill=ref({id:'',name:'',instruction:''}),accountAuth=ref(null);
let poll;
const providers={codex:'ChatGPT',deepseek:'DeepSeek',gemini:'Gemini',ollama:'Ollama'};
const presets=[{name:'Авиасейлс',url:'https://t.me/aviasales',topic:'Бренд и креатив'},{name:'DNative',url:'https://t.me/dnative',topic:'SMM и стратегия'},{name:'Русский маркетинг',url:'https://t.me/smmrus',topic:'Маркетинг и кейсы'},{name:'Топор Live',url:'https://t.me/toporlive',topic:'Новостные хуки'}];
const canManage=computed(()=>props.user?.admin||props.company?.owner_id===props.user?.id);
const artifacts=computed(()=>(data.value?.artifacts||[]).filter(v=>v.company_id===props.companyId&&v.kind!=='reply'&&(artifactKind.value==='all'||v.kind===artifactKind.value)));
const channels=computed(()=>(settings.value?.competitors||[]).filter(v=>v.username||v.imported));
const rankedPosts=computed(()=>channels.value.filter(c=>channelFilter.value==='all'||channelFilter.value===c.id).flatMap(c=>{
 const posts=(c.posts||[]).filter(p=>new Date(p.date)>=new Date(Date.now()-days.value*86400000));
 const known=posts.filter(p=>p.reactions!=null);const average=known.length?known.reduce((s,p)=>s+p.reactions,0)/known.length:0;
 return posts.map(p=>({...p,channel:c.name,key:c.id+':'+p.id,lift:average&&p.reactions!=null?p.reactions/average:null}));
}).sort((a,b)=>rankMode.value==='relative'?(b.lift??-1)-(a.lift??-1)||(b.reactions??-1)-(a.reactions??-1):(b.reactions??-1)-(a.reactions??-1)||b.date.localeCompare(a.date)));

const usage=computed(()=>(data.value?.usage||[]).filter(v=>v.company_id===props.companyId).sort((a,b)=>b.started_at.localeCompare(a.started_at)));
const monthUsage=computed(()=>usage.value.filter(v=>v.started_at.slice(0,7)===new Date().toISOString().slice(0,7)&&v.provider===providerView.value));
const providerHistory=computed(()=>usage.value.filter(v=>v.provider===providerView.value));
const tokenTotal=computed(()=>monthUsage.value.filter(v=>v.measured).reduce((sum,v)=>sum+v.input_tokens+v.output_tokens,0));
const inputTotal=computed(()=>monthUsage.value.filter(v=>v.measured).reduce((sum,v)=>sum+v.input_tokens,0));
const outputTotal=computed(()=>monthUsage.value.filter(v=>v.measured).reduce((sum,v)=>sum+v.output_tokens,0));
const cachedTotal=computed(()=>monthUsage.value.filter(v=>v.measured).reduce((sum,v)=>sum+v.cached_tokens,0));
const unknownUsage=computed(()=>monthUsage.value.filter(v=>!v.measured).length);
const windows=computed(()=>Object.values(data.value?.control?.quota?.limits||{}).flatMap(limit=>[limit.primary,limit.secondary].filter(Boolean).map(window=>({...window,name:limit.limitName||limit.limitId}))));
const availableSkills=computed(()=>[...(data.value?.skills||[]).filter(s=>s.id!=='reply'),...(settings.value?.skills||[])]);
const publishedPosts=computed(()=>(props.posts||[]).filter(p=>p.status==='published'));
const num=v=>v==null?'—':Number(v).toLocaleString('ru-RU');
const fmt=v=>v?new Date(v).toLocaleString('ru-RU',{timeZone:'Europe/Moscow',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})+' МСК':'—';
const parseIDs=text=>{const parts=text.split(',').map(v=>v.trim()).filter(Boolean);if(parts.some(v=>!/^\d+$/.test(v)||!Number.isSafeInteger(Number(v))||Number(v)<=0))throw Error('Укажите положительные числовые Telegram ID через запятую');return [...new Set(parts.map(Number))]};
const skillName=id=>availableSkills.value.find(s=>s.id===id)?.name||id;
async function load(reset=false){
 const result=await props.api('operations');data.value=result;
 if(props.mode==='control'&&props.user?.admin)accountAuth.value=await props.api('operations/auth');
 if(reset||!settings.value){
  settings.value=structuredClone(result.companies[props.companyId]);approvers.value=(settings.value?.policy?.approvers||[]).join(', ');
  control.value=structuredClone(result.control||{});admins.value=(control.value.admins||[props.user.id]).join(', ');
  for(const platform of ['vk','max']){const c=settings.value?.connections?.find(v=>v.platform===platform)||{};connections.value[platform]={...c,target:c.target||'',token:'',enabled:!!c.enabled,monitor:!!c.monitor}}
  for(const id of Object.keys(providers)){const c=control.value.providers?.[id]||{};providerForms.value[id]={...c,model:c.model||'',api_key:''}}
 } else if(settings.value){settings.value.competitors=result.companies[props.companyId]?.competitors||[]}
 if(props.mode==='analytics')report.value=await props.api(`operations/${props.companyId}/analytics?from=${from.value}&to=${to.value}`);
}
async function run(fn){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function saveSettings(){await run(async()=>{settings.value.policy.approvers=parseIDs(approvers.value);settings.value.auto_replies=false;await props.api(`operations/${props.companyId}/settings`,settings.value,'PUT');await load(true);notice.value='Правила компании сохранены';emit('updated')})}
async function saveControl(){await run(async()=>{await props.api('operations/control',{...control.value,admins:parseIDs(admins.value)},'PUT');await load(true);notice.value='Доступы и настройки AI сохранены';emit('updated')})}
async function saveProvider(activate=false){await run(async()=>{const id=providerView.value;await props.api(`operations/providers/${id}`,providerForms.value[id],'PUT');if(activate){await props.api('operations/control',{...control.value,provider:id,admins:parseIDs(admins.value)},'PUT')}await load(true);notice.value=activate?`${providers[id]} выбран для генерации текста`:'Настройки сохранены. Запросы к модели не выполнялись'})}
async function clearProviderKey(){await run(async()=>{const id=providerView.value;await props.api(`operations/providers/${id}`,{model:providerForms.value[id].model,clear_key:true},'PUT');await load(true);notice.value='API-ключ удалён'})}
async function refreshQuota(){await run(async()=>{await props.api('operations/quota',{});await load();notice.value='Лимиты ChatGPT обновлены'})}
async function connectAccount(){await run(async()=>{accountAuth.value=await props.api('operations/auth',{action:'start'});notice.value='Ожидаем ссылку и одноразовый код';await load()})}
async function cancelAccount(){await run(async()=>{await props.api('operations/auth',{action:'cancel'});await load()})}
async function createJob(kind=selectedKind.value,brief=request.value){await run(async()=>{const job=await props.api(`operations/${props.companyId}/jobs`,{kind,request:brief});request.value='';emit('task',job.id);await load();notice.value='Задача создана. Прогресс и уточнения доступны в диалоге с AI'})}
async function approveArtifact(v){await run(async()=>{await props.api(`operations/${props.companyId}/artifacts/${v.id}`,{});await load();notice.value='Материал утверждён'})}
async function addChannel(preset=channel.value){await run(async()=>{const v=await props.api(`operations/${props.companyId}/channels`,preset);channel.value={name:'',url:''};await load();notice.value='Канал добавлен. Загружаем последние посты…';try{await props.api(`operations/${props.companyId}/channels/${v.id}/scan`,{})}finally{await load()}notice.value='Посты и доступные счётчики загружены'})}
async function scanChannel(v){await run(async()=>{await props.api(`operations/${props.companyId}/channels/${v.id}/scan`,{});await load();notice.value='Посты обновлены'})}
function connectedChannel(preset){return channels.value.find(c=>c.url===preset.url)}
async function removeChannel(v){await run(async()=>{
 await props.api(`operations/${props.companyId}/channels/${v.id}`,null,'DELETE');
 if(channelFilter.value===v.id)channelFilter.value='all';
 await load();notice.value=`Канал «${v.name}» удалён из маркетинга`;emit('updated');
})}
async function importTelegram(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;await run(async()=>{if(file.size>10*1024*1024)throw Error('JSON должен быть до 10 МБ');const res=await fetch(`/api/operations/${props.companyId}/channels/import`,{method:'POST',headers:{...props.headers(),'Content-Type':'application/json'},body:await file.text()});const result=await res.json();if(!res.ok)throw Error(result.error);await load();notice.value='Выгрузка Telegram импортирована'})}
async function refreshMetrics(){await run(async()=>{const result=await props.api(`operations/${props.companyId}/metrics-refresh`,{});await load();notice.value=result.note})}
async function saveConnection(platform){await run(async()=>{await props.api(`operations/${props.companyId}/connections/${platform}`,connections.value[platform],'PUT');await load(true);notice.value='Подключение сохранено без проверки отправки'})}
async function revokeConnection(platform){await run(async()=>{await props.api(`operations/${props.companyId}/connections/${platform}`,{target:connections.value[platform].target,enabled:false,monitor:false,clear_token:true},'PUT');await load(true);notice.value='Токен удалён'})}
async function saveMetric(){await run(async()=>{const value={...metric.value};for(const key of ['reactions','comments'])value[key]=value[key]===''?null:Number(value[key]);await props.api(`operations/${props.companyId}/metrics`,value);await load();notice.value='Показатели сохранены'})}
async function importCSV(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;await run(async()=>{if(file.size>2*1024*1024)throw Error('CSV должен быть до 2 МБ');const res=await fetch(`/api/operations/${props.companyId}/metrics`,{method:'POST',headers:{...props.headers(),'Content-Type':'text/csv'},body:await file.text()});const result=await res.json();if(!res.ok)throw Error(result.error);await load();notice.value=`Импортировано строк: ${result.imported}`})}
function download(name,value,type='application/json'){const url=URL.createObjectURL(new Blob([value],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csvTemplate(){download('metrics-template.csv','post_id,date,reactions,comments\n','text/csv')}
function exportArtifact(v){download(`${v.kind}-v${v.version}.txt`,v.title+'\n\n'+v.body+'\n\n'+(v.data?JSON.stringify(v.data,null,2):''),'text/plain')}
function addSkill(){if(!newSkill.value.id||!newSkill.value.name||!newSkill.value.instruction){error.value='Заполните ID, название и инструкцию навыка';return}(settings.value.skills ||= []).push({...newSkill.value});newSkill.value={id:'',name:'',instruction:''};notice.value='Навык добавлен в форму. Сохраните правила компании'}
onMounted(async()=>{await run(()=>load(true));poll=setInterval(()=>load().catch(()=>{}),10000)});
onUnmounted(()=>clearInterval(poll));watch(()=>props.companyId,()=>run(()=>load(true)));watch(()=>props.mode,()=>run(()=>load()));
</script>

<template>
<div class="operations-panel">
 <div v-if="error" class="error-banner" role="alert">{{error}}</div><div v-if="notice" class="ops-notice" role="status">{{notice}}</div>
 <div v-if="!data" class="panel">Загружаем данные…</div>

 <template v-else-if="mode==='marketing'">
  <div class="page-heading"><div><div class="eyebrow">ИДЕИ ИЗ РЕАЛЬНЫХ ПУБЛИКАЦИЙ</div><h1>Маркетинг<span>.</span></h1><p>Telegram-каналы, популярные посты и темы для вашей компании.</p></div></div>
  <section class="panel ops-form">
   <div class="ops-row"><div><h3>Каналы для анализа</h3><p class="field-note">Подборка для вдохновения: креатив брендов, SMM и новостные хуки. Это референсы, их темы адаптируются к вашей компании.</p></div><label class="button secondary"><Upload :size="15"/>Импорт Telegram JSON<input hidden type="file" accept=".json,application/json" @change="importTelegram" :disabled="busy||!canManage"/></label></div>
   <div class="channel-presets"><article v-for="p in presets" :key="p.url" class="channel-preset"><b>{{p.name}}</b><small>{{p.topic}}</small><button v-if="connectedChannel(p)" class="preset-remove" :aria-label="`Удалить канал ${p.name}`" :disabled="busy||!canManage" @click="removeChannel(connectedChannel(p))"><Trash2 :size="13"/>Удалить</button><button v-else :disabled="busy||!canManage" @click="addChannel(p)"><Plus :size="13"/>Добавить</button></article></div>
   <form class="ops-inline" @submit.prevent="addChannel()"><label>Свой Telegram-канал<input v-model="channel.url" required placeholder="@канал или https://t.me/канал"/></label><button class="button secondary" :disabled="busy||!canManage"><Plus :size="15"/>Добавить канал</button></form>
   <div class="channel-list"><article v-for="v in channels" :key="v.id" class="ops-card"><div class="ops-row"><div><a v-if="v.url" :href="v.url" target="_blank" rel="noreferrer"><b>{{v.name}}</b> ↗</a><b v-else>{{v.name}}</b><small class="ops-block">{{v.posts?.length||0}} постов в выборке · {{fmt(v.scanned_at)}}{{v.imported?' · Импорт':''}}</small></div><div class="ops-actions"><button v-if="!v.imported" class="button secondary" :disabled="busy" @click="scanChannel(v)"><RefreshCw :size="14"/>Обновить</button><button class="button secondary channel-remove" :aria-label="`Удалить канал ${v.name}`" :disabled="busy||!canManage" @click="removeChannel(v)"><Trash2 :size="15"/>Удалить канал</button></div></div><p v-if="v.error" class="error-banner">{{v.error}}</p></article></div>
   <p v-if="!channels.length" class="empty-small">Каналов для анализа пока нет. Добавьте канал из подборки или по ссылке.</p>
   <p class="field-note">Публичная лента: до трёх последних страниц канала. Выборка может быть неполной. ≈ — счётчик Telegram округлён; платные звёзды не входят в реакции. Прочерк — значение недоступно. Закрытые каналы можно добавить выгрузкой Telegram Desktop в JSON.</p>
   <p v-if="busy" class="ops-notice" role="status">Выполняем действие… Загрузка постов может занять до минуты.</p>
  </section>
  <section class="panel ops-form"><div class="ops-row"><h3>Посты с высоким откликом</h3><div class="ops-actions"><select v-model="rankMode" aria-label="Сортировка постов"><option value="relative">Отклик внутри канала</option><option value="absolute">Число реакций</option></select><select v-model="channelFilter" aria-label="Канал рейтинга"><option value="all">Все каналы</option><option v-for="c in channels" :key="c.id" :value="c.id">{{c.name}}</option></select><select v-model.number="days" aria-label="Период рейтинга"><option :value="7">7 дней</option><option :value="30">30 дней</option><option :value="90">90 дней</option></select></div></div>
   <p class="field-note">По умолчанию сравниваем реакции со средним уровнем своего канала в выбранной выборке: крупные каналы не вытесняют небольшие. Можно переключиться на абсолютное число реакций. Свежесть определяется датой поста.</p>
   <div class="top-posts"><article v-for="(p,i) in rankedPosts.slice(0,12)" :key="p.key" class="ops-card"><div class="ops-row"><small>{{i+1}} · {{p.channel}}</small><small>{{fmt(p.date)}}</small></div><p class="post-excerpt">{{p.text?.slice(0,220)||'Медиапубликация без текста'}}{{p.text?.length>220?'…':''}}</p><div class="ops-row"><div class="post-counters"><small v-if="p.lift!=null">{{p.lift.toFixed(1)}}× среднего по каналу</small><b>{{p.approximate&&p.reactions!=null?'≈ ':''}}{{num(p.reactions)}} реакций</b><span>{{p.comments_approximate&&p.comments!=null?"≈ ":""}}{{num(p.comments)}} комментариев</span></div><a v-if="p.url" :href="p.url" target="_blank" rel="noreferrer">Открыть пост ↗</a></div></article></div>
   <p v-if="!rankedPosts.length" class="empty-small">Добавьте канал и загрузите посты. Затем выберите период.</p>
   <div class="ops-actions"><button class="button primary" :disabled="busy||!rankedPosts.length" @click="createJob('competitor',`Проанализируй посты Telegram за последние ${days} дней. Найди темы и хуки, которые собрали больше реакций относительно обычного уровня канала. Приведи ссылки, числа и даты; предложи применимые идеи для нашей компании.`)"><Sparkles :size="15"/>Проанализировать каналы</button><button class="button secondary" :disabled="busy||!rankedPosts.length" @click="createJob('topics',`Предложи актуальные темы для нашей компании по популярным постам подключённых Telegram-каналов за последние ${days} дней. Ссылайся на конкретные посты, сохрани стиль нашей компании.`)">Предложить темы</button></div>
  </section>
  <form class="panel ops-form" @submit.prevent="createJob()"><h3>Задача для маркетолога</h3><div class="ops-grid"><label>Что подготовить<select v-model="selectedKind"><option v-for="s in availableSkills" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>Цель и пожелания<textarea v-model="request" rows="3" placeholder="Например: темы для сотрудников на следующую неделю"></textarea></label></div><button class="button primary" :disabled="busy"><Sparkles :size="15"/>Подготовить материал</button></form>
  <section class="panel ops-form"><div class="ops-row"><h3>Сохранённые материалы</h3><select v-model="artifactKind" aria-label="Тип сохранённых материалов"><option value="all">Все материалы</option><option v-for="s in availableSkills" :key="s.id" :value="s.id">{{s.name}}</option></select></div><p v-if="!artifacts.length" class="empty-small">Здесь появятся результаты AI. Прогресс и уточнения — в диалоге на главном экране.</p><article v-for="v in artifacts" :key="v.id" class="ops-card"><small>{{skillName(v.kind)}} · версия {{v.version}} · {{fmt(v.created_at)}} · {{v.status==='approved'?'Утверждено':'Черновик'}}</small><h3>{{v.title}}</h3><pre class="ops-text">{{v.body}}</pre><div class="ops-actions"><button v-if="v.status!=='approved'&&canManage" class="button secondary" :disabled="busy" @click="approveArtifact(v)"><Check :size="15"/>Утвердить</button><button class="button secondary" @click="exportArtifact(v)"><Download :size="15"/>Скачать</button><button class="button secondary" @click="emit('task',v.task_id)">Открыть диалог</button></div><div v-if="Array.isArray(v.data?.items)" class="ops-ideas"><article v-for="(item,i) in v.data.items" :key="i"><b>{{item.date}} {{item.title}}</b><p>{{item.hook||item.brief}}</p><button class="button secondary" @click="emit('compose',`Подготовь публикацию: ${item.title}. ${item.hook||''} ${item.brief||''}. Цель: ${item.goal||''}`)">Создать пост по теме</button></article></div></article></section>
 </template>

 <template v-else-if="mode==='analytics'">
  <div class="page-heading"><div><div class="eyebrow">ПОНЯТНЫЕ ПОКАЗАТЕЛИ</div><h1>Аналитика<span>.</span></h1><p>Опубликованные посты, реакции и комментарии.</p></div></div>
  <section class="panel ops-form"><div class="ops-inline"><label>Публикации с<input v-model="from" type="date"/></label><label>по<input v-model="to" type="date"/></label><button class="button secondary" :disabled="busy" @click="run(()=>load())">Показать</button><button class="button secondary" :disabled="busy||!canManage" @click="refreshMetrics"><RefreshCw :size="15"/>Обновить из Telegram</button></div>
   <div class="ops-metrics three"><div><small>Опубликовано постов</small><strong>{{num(report?.totals?.posts??0)}}</strong><span>В выбранные даты</span></div><div><small>Реакции</small><strong>{{num(report?.totals?.reactions)}}</strong><span>Есть данные: {{report?.coverage?.reactions||0}} из {{report?.totals?.posts||0}} постов</span></div><div><small>Комментарии</small><strong>{{num(report?.totals?.comments)}}</strong><span>Есть данные: {{report?.coverage?.comments||0}} из {{report?.totals?.posts||0}} постов</span></div></div>
   <p class="field-note">{{report?.note}}</p>
   <div class="ops-table-wrap"><table><thead><tr><th>Публикация</th><th>Дата</th><th>Реакции</th><th>Комментарии</th><th>Источник</th></tr></thead><tbody><tr v-for="p in report?.posts||[]" :key="p.post_id"><td><a v-if="p.url" :href="p.url" target="_blank" rel="noreferrer">{{p.title}} ↗</a><span v-else>{{p.title}}</span></td><td>{{fmt(p.published_at)}}</td><td>{{num(p.reactions)}}</td><td>{{num(p.comments)}}</td><td>{{p.sources.map(s=>({telegram:'События Telegram',telegram_preview:'Лента Telegram',manual:'Ручной ввод',csv:'CSV',vk:'VK',max:'MAX'}[s]||s)).join(', ')||'Нет данных'}}</td></tr></tbody></table><p v-if="!report?.posts?.length" class="empty-small">В выбранном периоде ещё нет опубликованных через приложение постов.</p></div>
   <div class="ops-actions"><button class="button primary" :disabled="busy" @click="createJob('report',`Отчёт по публикациям с ${from} по ${to}: только посты, реакции и комментарии; объясни полноту данных и предложи действия.`)"><Sparkles :size="15"/>Отчёт с рекомендациями</button><button class="button secondary" @click="download('analytics.json',JSON.stringify(report,null,2))">Скачать данные</button></div>
  </section>
  <section class="panel ops-form"><details><summary>Добавить показатели вручную или из CSV</summary><div class="ops-form ops-details"><p class="field-note">Снимок накопительных счётчиков на дату. Пустые значения означают «не измерено». Используйте для постов, чья статистика недоступна автоматически.</p><div class="ops-actions"><label class="button secondary"><Upload :size="15"/>Загрузить CSV<input type="file" accept=".csv,text/csv" hidden @change="importCSV"/></label><button class="button secondary" @click="csvTemplate">Шаблон CSV</button></div><form class="ops-form" @submit.prevent="saveMetric"><label>Опубликованный пост<select v-model="metric.post_id" required><option value="" disabled>Выберите публикацию</option><option v-for="p in publishedPosts" :value="p.id" :key="p.id">{{p.title}} · {{p.id}}</option></select></label><div class="ops-grid"><label>Дата снимка<input v-model="metric.date" type="date" required/></label><label>Реакции<input v-model="metric.reactions" type="number" min="0"/></label><label>Комментарии<input v-model="metric.comments" type="number" min="0"/></label></div><button class="button secondary" :disabled="busy||!canManage">Сохранить показатели</button></form></div></details></section>
 </template>

 <template v-else-if="mode==='control'">
  <div class="page-heading"><div><div class="eyebrow">AI И РАСХОД</div><h1>Лимиты и доступы<span>.</span></h1><p>ChatGPT — процент подписки. Остальные модели — токены.</p></div></div>
  <div class="provider-tabs" role="tablist" aria-label="AI-провайдер"><button v-for="(label,id) in providers" :key="id" role="tab" :aria-selected="providerView===id" :class="{active:providerView===id}" @click="providerView=id">{{label}}<small v-if="(control?.provider||'codex')===id">Для текста</small></button></div>
  <section v-if="providerView==='codex'" class="panel ops-form"><div class="ops-row"><div><h3>Подписка ChatGPT</h3><p class="field-note">Доступ через подключённый аккаунт Codex. Это общий расход аккаунта, включая другие приложения и чаты.</p></div><button v-if="user?.admin" class="button secondary" :disabled="busy" @click="refreshQuota"><RefreshCw :size="15"/>Обновить</button></div>
   <div class="quota-grid"><article v-for="(v,i) in windows" :key="i" class="ops-quota"><small>{{v.name}}</small><div class="ops-row"><b>{{v.windowDurationMins>=10080?'Недельный лимит':v.windowDurationMins>=1440?'За '+Math.round(v.windowDurationMins/1440)+' дн.':'За '+Math.round(v.windowDurationMins/60)+' ч.'}}</b><strong>{{v.usedPercent}}%</strong></div><meter min="0" max="100" :value="v.usedPercent"></meter><small>Сброс: {{fmt(v.resetsAt*1000)}}</small></article></div>
   <p v-if="!windows.length" class="field-note">{{user?.admin?'Снимок лимитов ещё не получен. Нажмите «Обновить».':'Процент подписки доступен системному администратору.'}}</p><p v-if="data.control.quota?.error" class="error-banner">{{data.control.quota.error}}. Показан последний сохранённый снимок.</p><p class="field-note">Обновлено: {{fmt(data.control.quota?.at)}}. Проценты нельзя точно распределить между компаниями по числу токенов. Отдельный расход кредитов на изображения этот снимок не измеряет.</p>
  </section>
  <div class="ops-columns">
   <section v-if="user?.admin&&providerForms[providerView]" class="panel ops-form"><div class="ops-row"><h3>{{providers[providerView]}} · подключение</h3><span class="status-badge">{{providerView==='codex'?'Аккаунт':providerView==='ollama'?'Локально':providerForms[providerView].key_set?'Ключ сохранён':'Без API-ключа'}}</span></div>
    <label>Модель<input v-model="providerForms[providerView].model" maxlength="100" :placeholder="providerView==='codex'?'По умолчанию аккаунта':'Название модели'"/></label>
    <label v-if="['deepseek','gemini'].includes(providerView)">API-ключ<input v-model="providerForms[providerView].api_key" type="password" autocomplete="new-password" :placeholder="providerForms[providerView].key_set?'Сохранён; пусто — оставить прежний':'Можно добавить позже'"/></label>
    <p class="field-note">{{providerView==='ollama'?'Нужен запущенный Ollama с установленной моделью.':providerView==='codex'?'Используется текущая авторизация ChatGPT.':'Ключ хранится зашифрованным. Статистика токенов берётся из ответа API, неизвестный расход не заменяется нулём.'}} Сохранение настроек не запускает запрос к модели. Изображения создаются через ChatGPT.</p>
    <div class="ops-actions"><button class="button secondary" :disabled="busy" @click="saveProvider(false)">Сохранить настройки</button><button class="button primary" :disabled="busy||(['deepseek','gemini'].includes(providerView)&&!providerForms[providerView].key_set&&!providerForms[providerView].api_key)" @click="saveProvider(true)">Использовать для текста</button><button v-if="providerForms[providerView].key_set" class="button danger-text" :disabled="busy" @click="clearProviderKey">Удалить ключ</button></div>
    <details v-if="providerView==='codex'"><summary>Подключить другой аккаунт ChatGPT</summary><div class="ops-form ops-details"><p class="field-note">Вход сохраняется в отдельном профиле приложения. Пароль вводится только на странице OpenAI.</p><div v-if="accountAuth?.state==='waiting'" class="ops-card"><a v-if="accountAuth.url" :href="accountAuth.url" target="_blank" rel="noreferrer">Открыть вход в OpenAI ↗</a><b v-if="accountAuth.code">Код: {{accountAuth.code}}</b><span v-else>Получаем ссылку и код…</span><button class="button secondary" @click="cancelAccount">Отменить</button></div><button v-else class="button secondary" :disabled="busy" @click="connectAccount">Подключить аккаунт</button></div></details>
   </section>
   <section class="panel ops-form"><h3>{{providers[providerView]}} · эта компания</h3><small class="field-note">Текущий календарный месяц · UTC</small><div class="ops-metrics"><div><small>AI-вызовы</small><strong>{{monthUsage.length}}</strong></div><div v-if="providerView==='codex'"><small>Изображения</small><strong>{{monthUsage.filter(v=>v.kind==='image').length}}</strong></div><div v-else><small>Измеренные токены</small><strong>{{num(tokenTotal)}}</strong></div></div><template v-if="providerView!=='codex'"><div class="token-breakdown"><span>Вход <b>{{num(inputTotal)}}</b></span><span>Выход <b>{{num(outputTotal)}}</b></span><span>Кэш во входе <b>{{num(cachedTotal)}}</b></span></div><p class="field-note">Вход + выход = общий расход токенов. Кэш входит во входные токены и повторно не прибавляется. Вызовов без статистики: {{unknownUsage}}. Денежная стоимость не рассчитывается.</p></template><p v-else class="field-note">Расход ChatGPT показывается выше в процентах аккаунта. Здесь — только операции этой компании. Пересчёт вызовов в проценты не выполняется.</p></section>
  </div>
  <section class="panel ops-form"><h3>Журнал · {{providers[providerView]}}</h3><div class="ops-table-wrap"><table><thead><tr><th>Когда</th><th>Операция</th><th v-if="providerView!=='codex'">Токены: вход / выход</th><th>Статус</th></tr></thead><tbody><tr v-for="v in providerHistory.slice(0,60)" :key="v.id"><td>{{fmt(v.started_at)}}</td><td>{{v.kind==='image'?'Изображение':'Текст'}}<small class="ops-block">{{v.model||'Модель по умолчанию'}}</small></td><td v-if="providerView!=='codex'">{{v.measured?`${num(v.input_tokens)} / ${num(v.output_tokens)}`:'Неизвестно'}}</td><td>{{{running:'Выполняется',completed:'Завершено',failed:'Ошибка',interrupted:'Прервано'}[v.status]||v.status}}</td></tr></tbody></table><p v-if="!providerHistory.length" class="empty-small">Вызовов этого провайдера ещё не было.</p></div><p class="field-note">Учёт начался после включения журнала. Неуспешные попытки тоже записываются.</p><button class="button secondary" @click="download('ai-usage.json',JSON.stringify(providerHistory.map(v=>providerView==='codex'?{id:v.id,provider:v.provider,kind:v.kind,status:v.status,started_at:v.started_at}:v),null,2))">Скачать журнал</button></section>
  <form v-if="user?.admin&&control" class="panel ops-form" @submit.prevent="saveControl"><details><summary>Пауза, ограничения и системные администраторы</summary><div class="ops-form ops-details"><label class="ops-check"><input v-model="control.ai_paused" type="checkbox"/>Приостановить новые AI-вызовы всех компаний</label><label>Останавливать ChatGPT при расходе подписки, %<input v-model.number="control.stop_at_percent" type="number" min="0" max="100"/></label><p class="field-note">0 — порог выключен. Применяется только к ChatGPT. Уже начавшийся вызов может перейти порог. Лимиты других моделей задаются в правилах компании.</p><label>Администраторы · Telegram ID через запятую<input v-model="admins" required/></label><button class="button primary" :disabled="busy"><ShieldCheck :size="15"/>Сохранить</button></div></details></form>
 </template>
 <template v-else-if="mode==='settings'&&settings">
  <form v-if="section!=='connections'" class="panel ops-form" @submit.prevent="saveSettings"><h3>Правила согласования публикаций</h3><label>Ответственные · Telegram ID через запятую<input v-model="approvers" placeholder="Пусто — участники компании"/></label><label>Необходимое число одобрений<input v-model.number="settings.policy.required" type="number" min="1" max="10" required/></label><label class="ops-check"><input v-model="settings.policy.separate_author" type="checkbox"/>Автор задачи не может согласовывать собственный материал</label><label class="ops-check"><input v-model="settings.policy.confirm_checks" type="checkbox"/>Перед согласованием обязательно подтвердить проверку фактов и визуала</label><p class="field-note">Ответственные должны иметь доступ к компании. Изменение правил отменяет прежние одобрения готовых материалов.</p>
   <h3>Лимиты компании</h3><label class="ops-check"><input v-model="settings.usage.paused" type="checkbox"/>Приостановить новые AI-вызовы этой компании</label><div class="ops-grid"><label>Вызовов AI в месяц<input v-model.number="settings.usage.monthly_calls" type="number" min="0"/></label><label>Изображений в месяц<input v-model.number="settings.usage.monthly_images" type="number" min="0"/></label><label>Токенов DeepSeek / Gemini / Ollama в месяц<input v-model.number="settings.usage.monthly_tokens" type="number" min="0"/></label><label>Порог расхода ChatGPT, %<input v-model.number="settings.usage.stop_at_percent" type="number" min="0" max="100"/></label></div><p class="field-note">0 — без ограничения. Для ChatGPT применяется процент подписки. Порог токенов других моделей проверяется по накопленной статистике перед вызовом и не задаёт жёсткий предел ответа модели. При неизвестном расходе следующие вызовы блокируются до изменения ограничения. Вызовы без статистики остаются отдельно в журнале.</p>
   <h3>Автономный маркетинг</h3><label class="ops-check"><input v-model="settings.automation.enabled" type="checkbox"/>Включить автономную подготовку материалов и обновление Telegram-каналов</label><label class="ops-check"><input v-model="settings.automation.topics_daily" type="checkbox"/>Ежедневно предлагать темы</label><label class="ops-check"><input v-model="settings.automation.strategy_weekly" type="checkbox"/>Раз в неделю актуализировать стратегию</label><label class="ops-check"><input v-model="settings.automation.reports_weekly" type="checkbox"/>Раз в неделю готовить отчёт с выводами и рекомендациями</label><p class="field-note">Публикации продолжают требовать отдельного согласования. Подготовленные материалы доступны в разделе «Маркетинг».</p>
   <h3>Комментарии Telegram</h3><label>ID группы обсуждения<input v-model.number="settings.discussion_chat_id" type="number" placeholder="-100…"/></label><p class="field-note">Связанная с каналом группа нужна только для подсчёта новых комментариев. Бот должен получать её сообщения. Ответы не отправляются.</p>
   <h3>Свои навыки AI</h3><p class="field-note">Добавьте инструкцию нового типа маркетинговой задачи. Навык готовит внутренний материал и не получает права отправки или запуска команд.</p><div v-for="(s,i) in settings.skills||[]" :key="s.id" class="ops-row"><b>{{s.name}}</b><button type="button" class="button secondary" @click="settings.skills.splice(i,1)">Убрать из формы</button></div><label>ID навыка<input v-model="newSkill.id" placeholder="Например: employer_brand"/></label><label>Название навыка<input v-model="newSkill.name"/></label><label>Инструкция<textarea v-model="newSkill.instruction" rows="3" maxlength="6000"></textarea></label><button type="button" class="button secondary" @click="addSkill"><Plus :size="15"/>Добавить навык в форму</button><button class="button primary" :disabled="busy||!canManage">Сохранить правила компании</button>
  </form>
  <section v-if="section==='connections'" class="panel ops-form"><h3>Подключения площадок</h3><p class="field-note">VK и MAX подготовлены без токенов. Интеграции не тестировались. Перед реальным использованием потребуются токен, нужные права и проверка в тестовом канале.</p><form v-for="platform in ['vk','max']" :key="platform" class="ops-card ops-form" @submit.prevent="saveConnection(platform)"><h3>{{platform==='vk'?'ВКонтакте':'MAX'}}</h3><p>{{connections[platform].token_set?'Токен сохранён':'Токен не подключён'}} · {{connections[platform].verified?'Есть подтверждённый ответ площадки':'Подключение не проверено'}}</p><label>{{platform==='vk'?'ID сообщества':'ID канала'}}<input v-model="connections[platform].target" inputmode="numeric"/></label><label>Токен<input v-model="connections[platform].token" type="password" autocomplete="new-password" :placeholder="connections[platform].token_set?'Сохранён; оставьте пустым для сохранения':'Добавить позже'"/></label><label class="ops-check"><input v-model="connections[platform].enabled" type="checkbox"/>Включить подключение</label><label class="ops-check"><input v-model="connections[platform].monitor" type="checkbox"/>Собирать доступную статистику и комментарии</label><p v-if="connections[platform].last_error" class="error-banner">{{connections[platform].last_error}}</p><div class="ops-actions"><button class="button secondary" :disabled="busy||!canManage">Сохранить {{platform.toUpperCase()}}</button><button v-if="connections[platform].token_set" type="button" class="button danger-text" :disabled="busy||!canManage" @click="revokeConnection(platform)">Отключить и удалить токен</button></div></form></section>
 </template>
</div>
</template>

